import urllib.request,json,datetime,subprocess
root='http://127.0.0.1:17448'
paths=['/api/operator-lifecycle','/api/projects/control-plane?inspect=0','/api/projects/control-plane/cutover-r42/status','/api/managed-chat-status','/api/projects/managed-assignments','/api/health']
out={'at':datetime.datetime.now().isoformat(timespec='seconds'),'endpoints':{}}
for path in paths:
 try:
  with urllib.request.urlopen(root+path,timeout=6) as r:d=json.load(r)
  if not isinstance(d,dict):out['endpoints'][path]={'type':type(d).__name__};continue
  z={'keys':list(d.keys())[:35]}
  if path=='/api/operator-lifecycle':z['fields']={k:d.get(k) for k in ['object','mode','revision','quiesced','queuePaused','quiescence','state','status','resumeRequired']}
  if path=='/api/projects/control-plane?inspect=0':z['fields']={k:d.get(k) for k in ['object','status','state','ready','blocked','blockers','reason','checkedAt','summary','runtime','readiness']}
  if path=='/api/projects/control-plane/cutover-r42/status':z['fields']={k:d.get(k) for k in ['object','status','cutoverState','rollbackAvailable']}
  if path=='/api/projects/managed-assignments':z['fields']={'counts':d.get('counts'),'queue':d.get('queue'),'total':d.get('total'),'assignments_len':len(d.get('assignments',[])) if isinstance(d.get('assignments'),list) else None}
  if path=='/api/health':z['fields']={k:d.get(k) for k in ['state','ok','reasons','blockers','assignmentQueue']}
  out['endpoints'][path]=z
 except Exception as e:out['endpoints'][path]={'error':type(e).__name__+': '+str(e)[:90]}
print(json.dumps(out,ensure_ascii=True,default=str)[:15000])
